// Cuenta las labores PROGRAMADA retrasadas y próximas a través del gateway
// con la cuenta de servicio n8n, y arma la notificación (spec-n8n.md 2.5).
// Si no hay ninguna, no devuelve nada y el flujo termina sin enviar.
const parsear = (r) => (typeof r === 'string' ? JSON.parse(r) : r);
const dia = (desplazamiento) => new Date(Date.now() + desplazamiento * 86400000).toISOString().slice(0, 10);
const ayer = dia(-1), hoy = dia(0), manana = dia(1);

const token = parsear(await this.helpers.httpRequest({
  method: 'POST',
  url: $env.KEYCLOAK_TOKEN_URL,
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body: `grant_type=client_credentials&client_id=n8n&client_secret=${encodeURIComponent($env.N8N_CLIENT_SECRET)}`,
})).access_token;

async function contar(filtros) {
  let total = 0, cursor = null;
  do {
    const qs = { estado: 'PROGRAMADA', limite: 100, ...filtros };
    if (cursor) qs.cursor = cursor;
    const pagina = parsear(await this.helpers.httpRequest({
      url: `${$env.API_GATEWAY_URL}/api/operaciones/v1/labores`,
      qs,
      headers: { Authorization: `Bearer ${token}` },
    }));
    total += pagina.items.length;
    cursor = pagina.siguienteCursor;
  } while (cursor);
  return total;
}

const retrasadas = await contar.call(this, { fechaHasta: ayer });
const proximas = await contar.call(this, { fechaDesde: hoy, fechaHasta: manana });
if (retrasadas === 0 && proximas === 0) return [];

return [{
  json: {
    mensaje: {
      topic: 'tecnicos',
      notification: { title: 'Labores programadas', body: `${retrasadas} retrasadas y ${proximas} para hoy o mañana` },
      data: { tipo: 'RECORDATORIO_LABORES', retrasadas: String(retrasadas), proximas: String(proximas), fecha: hoy },
      android: { priority: 'high' },
    },
  },
}];
